-- ATELIER: execute todo este script no Supabase > SQL Editor > Run.
create extension if not exists pgcrypto;
create table if not exists public.subjects(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,description text default '',created_at timestamptz not null default now());
create table if not exists public.tasks(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,title text not null,description text default '',category text not null default 'project' check(category in('study','project')),status text not null default 'todo' check(status in('todo','doing','done')),due_date date,created_at timestamptz not null default now());
create table if not exists public.notes(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,title text not null,content text not null default '',created_at timestamptz not null default now());
create table if not exists public.folders(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,created_at timestamptz not null default now());
create table if not exists public.documents(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,storage_path text not null,mime_type text,size bigint not null default 0,created_at timestamptz not null default now());
alter table public.subjects enable row level security;alter table public.tasks enable row level security;alter table public.notes enable row level security;alter table public.folders enable row level security;alter table public.documents enable row level security;
drop policy if exists "own subjects" on public.subjects;create policy "own subjects" on public.subjects for all to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);
drop policy if exists "own tasks" on public.tasks;create policy "own tasks" on public.tasks for all to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);
drop policy if exists "own notes" on public.notes;create policy "own notes" on public.notes for all to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);
drop policy if exists "own folders" on public.folders;create policy "own folders" on public.folders for all to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);
drop policy if exists "own documents" on public.documents;create policy "own documents" on public.documents for all to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('atelier-documents','atelier-documents',false,20971520,array['application/pdf','application/msword','application/vnd.openxmlformats-officedocument.wordprocessingml.document','application/vnd.ms-excel','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet','application/vnd.ms-powerpoint','application/vnd.openxmlformats-officedocument.presentationml.presentation','text/plain','image/png','image/jpeg','image/webp']) on conflict(id) do update set public=false,file_size_limit=20971520,allowed_mime_types=excluded.allowed_mime_types;
drop policy if exists "own atelier storage" on storage.objects;create policy "own atelier storage" on storage.objects for all to authenticated using(bucket_id='atelier-documents' and (storage.foldername(name))[1]=auth.uid()::text) with check(bucket_id='atelier-documents' and (storage.foldername(name))[1]=auth.uid()::text);
